// EMBER voice endpoint: ElevenLabs speech-to-text (Scribe) and text-to-speech. Keys stay server-side.
//   GET  /api/voice?op=status        -> { stt, tts }
//   POST /api/voice?op=stt  (audio/wav body)  -> { text }
//   POST /api/voice?op=tts  { text }          -> audio/mpeg
// SI disclosure: written with assistance from Claude (Anthropic). Voice generated by ElevenLabs (SI).
const EL = 'https://api.elevenlabs.io/v1'

async function raw(req) {
  if (Buffer.isBuffer(req.body)) return req.body
  if (typeof req.body === 'string') return Buffer.from(req.body)
  const chunks = []; for await (const c of req) chunks.push(c)
  return Buffer.concat(chunks)
}

export default async function handler(req, res) {
  const key = process.env.ELEVENLABS_API_KEY
  const op = new URL(req.url, 'http://x').searchParams.get('op')
  const json = (code, obj) => { res.statusCode = code; res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify(obj)) }
  if (op === 'status') return json(200, { stt: !!key, tts: !!key })
  if (!key) return json(503, { error: 'ELEVENLABS_API_KEY is not set on the server.' })
  if (req.method !== 'POST') return json(405, { error: 'POST only' })

  try {
    if (op === 'stt') {
      const audio = await raw(req)
      if (!audio.length || audio.length > 4_000_000) return json(400, { error: 'Bad audio size.' })
      const form = new FormData()
      form.append('file', new Blob([audio], { type: 'audio/wav' }), 'speech.wav')
      form.append('model_id', process.env.ELEVENLABS_STT_MODEL || 'scribe_v1')
      form.append('language_code', 'en')
      form.append('tag_audio_events', 'false')
      const r = await fetch(`${EL}/speech-to-text`, { method: 'POST', headers: { 'xi-api-key': key }, body: form })
      const j = await r.json().catch(() => ({}))
      if (!r.ok) return json(502, { error: j.detail?.message || j.detail || `STT HTTP ${r.status}` })
      return json(200, { text: String(j.text || '').trim() })
    }
    if (op === 'tts') {
      const b = JSON.parse((await raw(req)).toString('utf8') || '{}')
      const text = String(b.text || '').slice(0, 1200).trim()
      if (!text) return json(400, { error: 'No text.' })
      const voice = process.env.ELEVENLABS_VOICE_ID || 'JBFqnCBsd6RMkjVDRZzb'
      const r = await fetch(`${EL}/text-to-speech/${voice}?output_format=mp3_44100_128`, {
        method: 'POST', headers: { 'xi-api-key': key, 'Content-Type': 'application/json', Accept: 'audio/mpeg' },
        body: JSON.stringify({ text, model_id: process.env.ELEVENLABS_TTS_MODEL || 'eleven_flash_v2_5',
          voice_settings: { stability: 0.45, similarity_boost: 0.8, style: 0.15, use_speaker_boost: true } }),
      })
      if (!r.ok) { const j = await r.json().catch(() => ({})); return json(502, { error: j.detail?.message || j.detail || `TTS HTTP ${r.status}` }) }
      res.statusCode = 200; res.setHeader('Content-Type', 'audio/mpeg'); res.setHeader('Cache-Control', 'no-store')
      res.end(Buffer.from(await r.arrayBuffer()))
      return
    }
    return json(400, { error: 'Unknown op.' })
  } catch (e) { return json(500, { error: String(e.message || e) }) }
}
